"use client";

import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";
import "./plus-menu.css";

export type PlusMenuItem = { label: string; hint?: string; icon: ReactNode; onSelect: () => void };

/* The + grows into the menu it opens. Anchored at its
   bottom-right corner, so it opens up and to the left. Put it wherever the
   + should sit; it sizes the open menu from the number of items. */
export default function PlusMenu({ items, label = "Add" }: { items: PlusMenuItem[]; label?: string }) {
  const [open, setOpen] = useState(false);
  const box = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: PointerEvent) => {
      if (box.current && !box.current.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    document.addEventListener("pointerdown", onDoc);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onDoc);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  return (
    <>
      <div className={"ob-plus-scrim" + (open ? " is-on" : "")} aria-hidden="true" />
      <div className="ob-plus" ref={box} style={{ "--ob-plus-items": items.length } as CSSProperties}>
        <div className="ob-plus-morph" data-open={open}>
          <div className="ob-plus-menu" role="menu" aria-hidden={!open}>
            {items.map((it) => (
              <button
                key={it.label}
                type="button"
                role="menuitem"
                className="ob-plus-item"
                tabIndex={open ? 0 : -1}
                onClick={() => {
                  setOpen(false);
                  it.onSelect();
                }}
              >
                <span className="ob-plus-icon">{it.icon}</span>
                <span className="ob-plus-text">
                  <span>{it.label}</span>
                  {it.hint && <span className="ob-plus-hint">{it.hint}</span>}
                </span>
              </button>
            ))}
          </div>
          <button
            type="button"
            className="ob-plus-button"
            aria-expanded={open}
            aria-label={label}
            onClick={() => setOpen((o) => !o)}
          >
            <svg width="22" height="22" viewBox="0 0 22 22" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <path d="M11 4v14M4 11h14" />
            </svg>
          </button>
        </div>
      </div>
    </>
  );
}

/* Plus menu: the + grows into the menu it opens, sized for a thumb. The open
   height follows the item count. */

:where(:root) {
  --ob-plus-open-dur: 420ms;
  --ob-plus-close-dur: 300ms;
  --ob-plus-ease: cubic-bezier(0.32, 0.9, 0.3, 1);
}

.ob-plus {
  --ob-plus-size: 58px;
  --ob-plus-width: 264px;
  --ob-plus-row: 58px;
  --ob-plus-open-h: calc(var(--ds-space-md) + var(--ob-plus-items) * (var(--ob-plus-row) + 2px));
  position: relative; z-index: 2; width: var(--ob-plus-size); height: var(--ob-plus-size); flex: none; pointer-events: auto;
}
.ob-plus-morph {
  position: absolute; right: 0; bottom: 0; overflow: hidden;
  width: var(--ob-plus-size); height: var(--ob-plus-size);
  border-radius: calc(var(--ob-plus-size) / 2);
  background: var(--ds-color-text); color: var(--ds-color-bg);
  box-shadow: var(--ob-shadow-float, var(--ds-shadow-lg));
  transition:
    width var(--ob-plus-close-dur) var(--ob-plus-ease),
    height var(--ob-plus-close-dur) var(--ob-plus-ease),
    border-radius var(--ob-plus-close-dur) var(--ob-plus-ease);
}
.ob-plus-morph[data-open="true"] {
  width: var(--ob-plus-width); height: var(--ob-plus-open-h);
  border-radius: var(--ds-radius-xl);
  transition-duration: var(--ob-plus-open-dur);
}
.ob-plus-button {
  position: absolute; right: 0; bottom: 0; z-index: 1;
  width: var(--ob-plus-size); height: var(--ob-plus-size);
  display: grid; place-items: center;
  color: inherit; border: 0; background: none; padding: 0; cursor: pointer;
}
/* The + fades as the menu takes its place. Tapping outside or Escape closes. */
.ob-plus-button { transition: opacity var(--ds-duration-base) var(--ds-ease-out) 80ms, rotate var(--ob-plus-close-dur) var(--ob-plus-ease); }
.ob-plus-morph[data-open="true"] .ob-plus-button { opacity: 0; rotate: 45deg; pointer-events: none; transition: opacity var(--ds-duration-fast) var(--ds-ease-in), rotate var(--ob-plus-open-dur) var(--ob-plus-ease); }
.ob-plus-menu {
  position: absolute; right: 0; bottom: 0;
  width: var(--ob-plus-width); height: var(--ob-plus-open-h);
  padding: var(--ds-space-xs); display: grid; align-content: start; gap: 2px;
  opacity: 0; translate: 0 8px; pointer-events: none;
  transition: opacity var(--ds-duration-fast) var(--ds-ease-in), translate var(--ds-duration-fast) var(--ds-ease-in);
}
.ob-plus-morph[data-open="true"] .ob-plus-menu {
  opacity: 1; translate: 0; pointer-events: auto;
  transition: opacity var(--ds-duration-base) var(--ds-ease-out) 120ms, translate var(--ds-duration-base) var(--ds-ease-out) 120ms;
}
.ob-plus-item {
  display: flex; align-items: center; gap: var(--ds-space-sm); width: 100%; height: var(--ob-plus-row); padding: 0 var(--ds-space-xs);
  border: 0; background: none; font: inherit; cursor: pointer;
  border-radius: var(--ds-radius-lg); text-align: left; color: inherit;
}
.ob-plus-item:hover, .ob-plus-item:focus-visible { background: color-mix(in srgb, var(--ds-color-bg) 12%, transparent); outline: none; }
.ob-plus-icon { width: 38px; height: 38px; border-radius: var(--ds-radius-md); background: color-mix(in srgb, var(--ds-color-bg) 14%, transparent); display: grid; place-items: center; flex: none; }
.ob-plus-text { display: grid; font-weight: var(--ds-weight-semibold); font-size: var(--ds-type-ui-size); line-height: 1.25; }
.ob-plus-hint { font-size: var(--ds-type-label-size); font-weight: var(--ds-weight-medium); opacity: 0.6; }
.ob-plus-scrim {
  position: fixed; inset: 0; z-index: 0; background: var(--ob-shade, rgba(10, 10, 8, 0.28));
  opacity: 0; pointer-events: none;
  transition: opacity var(--ob-plus-close-dur) var(--ob-plus-ease);
}
.ob-plus-scrim.is-on { opacity: 1; pointer-events: auto; transition-duration: var(--ob-plus-open-dur); }
@media (prefers-reduced-motion: reduce) {
  .ob-plus-scrim, .ob-plus-morph, .ob-plus-menu, .ob-plus-button { transition: none !important; }
}
